SELECT fe.*, s.semester_name, s.year, s.is_current, GROUP_CONCAT(CASE WHEN fet.invigilate_role = '主监考' THEN t.name END) as main_teacher_name, GROUP_CONCAT(CASE WHEN fet.invigilate_role IN ('副监考', '副监考1') THEN t.name END) as sub_teacher_name, GROUP_CONCAT(CASE WHEN fet.invigilate_role = '副监考2' THEN t.name END) as sub_teacher2_name, GROUP_CONCAT(CASE WHEN fet.invigilate_role = '副监考3' THEN t.name END) as sub_teacher3_name FROM FINAL_EXAM fe LEFT JOIN SEMESTER s ON fe.semester_id = s.semester_id LEFT JOIN FINAL_EXAM_TEACHER fet ON fe.exam_id = fet.exam_id LEFT JOIN TEACHER t ON fet.teacher_id = t.teacher_id
AND fe.course_name LIKE CONCAT('%', #{query.courseName}, '%')
AND fe.semester_id = #{query.semesterId}
AND fe.status = #{query.status}
AND fe.room LIKE CONCAT('%', #{query.room}, '%')
AND fe.exam_id IN ( SELECT exam_id FROM FINAL_EXAM_TEACHER WHERE teacher_id = #{query.teacherId} )
AND fe.exam_id IN ( SELECT fet2.exam_id FROM FINAL_EXAM_TEACHER fet2 LEFT JOIN TEACHER t2 ON fet2.teacher_id = t2.teacher_id WHERE t2.name LIKE CONCAT('%', #{query.teacherName}, '%') )
AND fe.start_time >= #{query.startTime}
AND fe.end_time <= #{query.endTime}
GROUP BY fe.exam_id ORDER BY fe.exam_id DESC LIMIT #{query.pageSize} OFFSET ${(query.pageNum - 1) * query.pageSize}

SELECT COUNT(DISTINCT fe.exam_id)
FROM FINAL_EXAM fe
LEFT JOIN FINAL_EXAM_TEACHER fet ON fe.exam_id = fet.exam_id
LEFT JOIN TEACHER t ON fet.teacher_id = t.teacher_id

    
        AND fe.course_name LIKE CONCAT('%', #{query.courseName}, '%')
    
    
        AND fe.semester_id = #{query.semesterId}
    
    
        AND fe.status = #{query.status}
    
    
        AND fe.room LIKE CONCAT('%', #{query.room}, '%')
    
    
        AND fe.exam_id IN (
            SELECT exam_id FROM FINAL_EXAM_TEACHER WHERE teacher_id = #{query.teacherId}
        )
    
    
        AND fe.exam_id IN (
            SELECT fet2.exam_id
            FROM FINAL_EXAM_TEACHER fet2
            LEFT JOIN TEACHER t2 ON fet2.teacher_id = t2.teacher_id
            WHERE t2.name LIKE CONCAT('%', #{query.teacherName}, '%')
        )
    
    
        AND fe.start_time >= #{query.startTime}
    
    
        AND fe.end_time <= #{query.endTime}
